    },
    {
      "name": "industry_vertical",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.9,
      "hallucination_observed": false,
      "rationale": "Provides a solid grouping axis; somewhat overlaps business_model_type but adds finer sector granularity. Sample values (healthcare_biotech, venture_capital, fintech_finance) are sound readings."
    },
    {
      "name": "company_maturity",
      "analytical_usefulness": 0.7,
      "source_groundedness": 0.55,
